WITH exploded AS (SELECT id, code FROM carts LATERAL VIEW EXPLODE(coupon_codes) e AS code), cleaned AS (SELECT *, SUBSTRING(code, 1, 2) AS code_prefix, CASE WHEN code = 'WELCOME5' THEN 1 ELSE 0 END AS is_welcome5 FROM exploded WHERE code = 'WELCOME5'), enriched AS (SELECT *, MIN(is_welcome5) OVER (PARTITION BY code) AS code_min_is_welcome5, RANK() OVER (ORDER BY is_welcome5 DESC NULLS FIRST) AS is_welcome5_rank FROM cleaned), filtered AS (SELECT *, INITCAP(TRIM(code)) AS code_title, COALESCE(code, 'N/A') AS code_clean FROM enriched WHERE code = 'WELCOME5') SELECT id, code, code_prefix, is_welcome5, code_min_is_welcome5, is_welcome5_rank, code_title, code_clean FROM filtered ORDER BY is_welcome5_rank DESC NULLS FIRST
